with latest as (select * from orders qualify row_number() over (partition by store_id, channel order by order_date desc, id) = 1) select id, customer_id, order_date, status, channel, amount, discount, case when status rlike '^(CANCELLED|PENDING)$' then 'OTHER_ZONE' when status rlike '^(COMPLETED|SHIPPED)$' then 'GROUP_A' else 'EXTENDED' end as status_zone from latest order by status_zone;
